INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100101, 0, "", "vo_empress_100101_001", "vo_empress_100101_001", 4, 5, 1, "ヒヨリ", "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！", "", 1);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100103, 0, "", "vo_empress_100101_002", "vo_empress_100101_002", 4, 5, 1, "ヒヨリ", "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！", "", 2);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100103, 0, "", "vo_empress_100101_003", "vo_empress_100101_003", 4, 5, 2, "ヒヨリ", "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！", "", 3);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100102, 100101, "", "vo_empress_100101_004", "vo_empress_100101_004", 4, 5, 3, "ヒヨリ", "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！", "", 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100203, 0, "", "vo_empress_100201_001", "vo_empress_100201_001", 4, 5, 1, "ユイ", "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン", "", 5);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100203, 0, "", "vo_empress_100201_002", "vo_empress_100201_002", 4, 5, 1, "ユイ", "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！", "", 6);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100203, 0, "", "vo_empress_100201_003", "vo_empress_100201_003", 4, 5, 2, "ユイ", "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！", "", 7);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100202, 100201, "", "vo_empress_100201_004", "vo_empress_100201_004", 4, 5, 3, "ユイ", "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！", "", 8);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100301, 0, "", "vo_empress_100301_001", "vo_empress_100301_001", 4, 5, 1, "レイ", "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう", "", 9);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100303, 0, "", "vo_empress_100301_002", "vo_empress_100301_002", 4, 5, 1, "レイ", "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！", "", 10);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100303, 0, "", "vo_empress_100301_003", "vo_empress_100301_003", 4, 5, 2, "レイ", "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！", "", 11);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100302, 100301, "", "vo_empress_100301_004", "vo_empress_100301_004", 4, 5, 3, "レイ", "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！", "", 12);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100401, 0, "", "vo_empress_100401_001", "vo_empress_100401_001", 4, 5, 1, "ミソギ", "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！", "", 13);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100401, 0, "", "vo_empress_100401_002", "vo_empress_100401_002", 4, 5, 1, "ミソギ", "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！", "", 14);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100403, 0, "", "vo_empress_100401_003", "vo_empress_100401_003", 4, 5, 2, "ミソギ", "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？", "", 15);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100402, 100401, "", "vo_empress_100401_004", "vo_empress_100401_004", 4, 5, 3, "ミソギ", "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！", "", 16);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100501, 0, "", "vo_empress_100501_001", "vo_empress_100501_001", 4, 5, 1, "マツリ", "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～", "", 17);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100501, 0, "", "vo_empress_100501_002", "vo_empress_100501_002", 4, 5, 1, "マツリ", "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！", "", 18);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100503, 0, "", "vo_empress_100501_003", "vo_empress_100501_003", 4, 5, 2, "マツリ", "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！", "", 19);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100502, 100501, "", "vo_empress_100501_004", "vo_empress_100501_004", 4, 5, 3, "マツリ", "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！", "", 20);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100603, 0, "", "vo_empress_100601_001", "vo_empress_100601_001", 4, 5, 1, "アカリ", "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ", "", 21);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100601, 0, "", "vo_empress_100601_002", "vo_empress_100601_002", 4, 5, 1, "アカリ", "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！", "", 22);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100603, 0, "", "vo_empress_100601_003", "vo_empress_100601_003", 4, 5, 2, "アカリ", "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…", "", 23);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100602, 100601, "", "vo_empress_100601_004", "vo_empress_100601_004", 4, 5, 3, "アカリ", "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！", "", 24);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100701, 0, "", "vo_empress_100701_001", "vo_empress_100701_001", 4, 5, 1, "ミヤコ", "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！", "", 25);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100702, 0, "", "vo_empress_100701_002", "vo_empress_100701_002", 4, 5, 1, "ミヤコ", "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！", "", 26);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100703, 0, "", "vo_empress_100701_003", "vo_empress_100701_003", 4, 5, 2, "ミヤコ", "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！", "", 27);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100702, 100701, "", "vo_empress_100701_004", "vo_empress_100701_004", 4, 5, 3, "ミヤコ", "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！", "", 28);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100801, 0, "", "vo_empress_100801_001", "vo_empress_100801_001", 4, 5, 1, "ユキ", "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！", "", 29);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100801, 0, "", "vo_empress_100801_002", "vo_empress_100801_002", 4, 5, 1, "ユキ", "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね", "", 30);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100801, 0, "", "vo_empress_100801_003", "vo_empress_100801_003", 4, 5, 2, "ユキ", "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね", "", 31);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100802, 100801, "", "vo_empress_100801_004", "vo_empress_100801_004", 4, 5, 3, "ユキ", "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの", "", 32);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100901, 0, "", "vo_empress_100901_001", "vo_empress_100901_001", 4, 5, 1, "アンナ", "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！", "", 33);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100903, 0, "", "vo_empress_100901_002", "vo_empress_100901_002", 4, 5, 1, "アンナ", "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！", "", 34);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100903, 0, "", "vo_empress_100901_003", "vo_empress_100901_003", 4, 5, 2, "アンナ", "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ", "", 35);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 100902, 100901, "", "vo_empress_100901_004", "vo_empress_100901_004", 4, 5, 3, "アンナ", "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！", "", 36);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101001, 0, "", "vo_empress_101001_001", "vo_empress_101001_001", 4, 5, 1, "マホ", "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！", "", 37);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101001, 0, "", "vo_empress_101001_002", "vo_empress_101001_002", 4, 5, 1, "マホ", "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪", "", 38);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101003, 0, "", "vo_empress_101001_003", "vo_empress_101001_003", 4, 5, 2, "マホ", "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！", "", 39);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101002, 101001, "", "vo_empress_101001_004", "vo_empress_101001_004", 4, 5, 3, "マホ", "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！", "", 40);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101101, 0, "", "vo_empress_101101_001", "vo_empress_101101_001", 4, 5, 1, "リノ", "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？", "", 41);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101101, 0, "", "vo_empress_101101_002", "vo_empress_101101_002", 4, 5, 1, "リノ", "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！", "", 42);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101103, 0, "", "vo_empress_101101_003", "vo_empress_101101_003", 4, 5, 2, "リノ", "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！", "", 43);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101102, 101101, "", "vo_empress_101101_004", "vo_empress_101101_004", 4, 5, 3, "リノ", "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！", "", 44);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101201, 0, "", "vo_empress_101201_001", "vo_empress_101201_001", 4, 5, 1, "ハツネ", "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！", "", 45);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101202, 0, "", "vo_empress_101201_002", "vo_empress_101201_002", 4, 5, 1, "ハツネ", "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…", "", 46);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101203, 0, "", "vo_empress_101201_003", "vo_empress_101201_003", 4, 5, 2, "ハツネ", "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…", "", 47);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101202, 101201, "", "vo_empress_101201_004", "vo_empress_101201_004", 4, 5, 3, "ハツネ", "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！", "", 48);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101301, 0, "", "vo_empress_101301_001", "vo_empress_101301_001", 4, 5, 1, "ナナカ", "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！", "", 49);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101301, 0, "", "vo_empress_101301_002", "vo_empress_101301_002", 4, 5, 1, "ナナカ", "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！", "", 50);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101303, 0, "", "vo_empress_101301_003", "vo_empress_101301_003", 4, 5, 2, "ナナカ", "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？", "", 51);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101302, 101301, "", "vo_empress_101301_004", "vo_empress_101301_004", 4, 5, 3, "ナナカ", "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！", "", 52);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101401, 0, "", "vo_empress_101401_001", "vo_empress_101401_001", 4, 5, 1, "カスミ", "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！", "", 53);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101401, 0, "", "vo_empress_101401_002", "vo_empress_101401_002", 4, 5, 1, "カスミ", "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？", "", 54);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101403, 0, "", "vo_empress_101401_003", "vo_empress_101401_003", 4, 5, 2, "カスミ", "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！", "", 55);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101402, 101401, "", "vo_empress_101401_004", "vo_empress_101401_004", 4, 5, 3, "カスミ", "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！", "", 56);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101501, 0, "", "vo_empress_101501_001", "vo_empress_101501_001", 4, 5, 1, "ミサト", "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！", "", 57);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101501, 0, "", "vo_empress_101501_002", "vo_empress_101501_002", 4, 5, 1, "ミサト", "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！", "", 58);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101501, 0, "", "vo_empress_101501_003", "vo_empress_101501_003", 4, 5, 2, "ミサト", "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね", "", 59);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101502, 101501, "", "vo_empress_101501_004", "vo_empress_101501_004", 4, 5, 3, "ミサト", "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪", "", 60);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101601, 0, "", "vo_empress_101601_001", "vo_empress_101601_001", 4, 5, 1, "スズナ", "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！", "", 61);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101601, 0, "", "vo_empress_101601_002", "vo_empress_101601_002", 4, 5, 1, "スズナ", "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪", "", 62);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101601, 0, "", "vo_empress_101601_003", "vo_empress_101601_003", 4, 5, 2, "スズナ", "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！", "", 63);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101602, 101601, "", "vo_empress_101601_004", "vo_empress_101601_004", 4, 5, 3, "スズナ", "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪", "", 64);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101701, 0, "", "vo_empress_101701_001", "vo_empress_101701_001", 4, 5, 1, "カオリ", "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！", "", 65);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101701, 0, "", "vo_empress_101701_002", "vo_empress_101701_002", 4, 5, 1, "カオリ", "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪", "", 66);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101703, 0, "", "vo_empress_101701_003", "vo_empress_101701_003", 4, 5, 2, "カオリ", "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？", "", 67);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101702, 101701, "", "vo_empress_101701_004", "vo_empress_101701_004", 4, 5, 3, "カオリ", "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！", "", 68);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101801, 0, "", "vo_empress_101801_001", "vo_empress_101801_001", 4, 5, 1, "イオ", "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！", "", 69);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101801, 0, "", "vo_empress_101801_002", "vo_empress_101801_002", 4, 5, 1, "イオ", "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！", "", 70);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101803, 0, "", "vo_empress_101801_003", "vo_empress_101801_003", 4, 5, 2, "イオ", "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！", "", 71);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 101802, 101801, "", "vo_empress_101801_004", "vo_empress_101801_004", 4, 5, 3, "イオ", "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪", "", 72);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102003, 0, "", "vo_empress_102001_001", "vo_empress_102001_001", 4, 5, 1, "ミミ", "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！", "", 73);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102003, 0, "", "vo_empress_102001_002", "vo_empress_102001_002", 4, 5, 1, "ミミ", "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！", "", 74);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102003, 0, "", "vo_empress_102001_003", "vo_empress_102001_003", 4, 5, 2, "ミミ", "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…", "", 75);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102002, 102001, "", "vo_empress_102001_004", "vo_empress_102001_004", 4, 5, 3, "ミミ", "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！", "", 76);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102101, 0, "", "vo_empress_102101_001", "vo_empress_102101_001", 4, 5, 1, "クルミ", "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！", "", 77);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102101, 0, "", "vo_empress_102101_002", "vo_empress_102101_002", 4, 5, 1, "クルミ", "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！", "", 78);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102101, 0, "", "vo_empress_102101_003", "vo_empress_102101_003", 4, 5, 2, "クルミ", "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ", "", 79);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102102, 102101, "", "vo_empress_102101_004", "vo_empress_102101_004", 4, 5, 3, "クルミ", "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！", "", 80);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102201, 0, "", "vo_empress_102201_001", "vo_empress_102201_001", 4, 5, 1, "ヨリ", "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！", "", 81);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102201, 0, "", "vo_empress_102201_002", "vo_empress_102201_002", 4, 5, 1, "ヨリ", "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！", "", 82);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102203, 0, "", "vo_empress_102201_003", "vo_empress_102201_003", 4, 5, 2, "ヨリ", "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！", "", 83);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102202, 102201, "", "vo_empress_102201_004", "vo_empress_102201_004", 4, 5, 3, "ヨリ", "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！", "", 84);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102301, 0, "", "vo_empress_102301_001", "vo_empress_102301_001", 4, 5, 1, "アヤネ", "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』", "", 85);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102303, 0, "", "vo_empress_102301_002", "vo_empress_102301_002", 4, 5, 1, "アヤネ", "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！", "", 86);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102303, 0, "", "vo_empress_102301_003", "vo_empress_102301_003", 4, 5, 2, "アヤネ", "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』", "", 87);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102302, 102301, "", "vo_empress_102301_004", "vo_empress_102301_004", 4, 5, 3, "アヤネ", "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪", "", 88);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102503, 0, "", "vo_empress_102501_001", "vo_empress_102501_001", 4, 5, 1, "スズメ", "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！", "", 89);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102503, 0, "", "vo_empress_102501_002", "vo_empress_102501_002", 4, 5, 1, "スズメ", "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！", "", 90);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102503, 0, "", "vo_empress_102501_003", "vo_empress_102501_003", 4, 5, 2, "スズメ", "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！", "", 91);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102502, 102501, "", "vo_empress_102501_004", "vo_empress_102501_004", 4, 5, 3, "スズメ", "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！", "", 92);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102603, 0, "", "vo_empress_102601_001", "vo_empress_102601_001", 4, 5, 1, "リン", "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー", "", 93);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102603, 0, "", "vo_empress_102601_002", "vo_empress_102601_002", 4, 5, 1, "リン", "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！", "", 94);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102603, 0, "", "vo_empress_102601_003", "vo_empress_102601_003", 4, 5, 2, "リン", "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー", "", 95);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102602, 102601, "", "vo_empress_102601_004", "vo_empress_102601_004", 4, 5, 3, "リン", "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！", "", 96);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102701, 0, "", "vo_empress_102701_001", "vo_empress_102701_001", 4, 5, 1, "エリコ", "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…", "", 97);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102701, 0, "", "vo_empress_102701_002", "vo_empress_102701_002", 4, 5, 1, "エリコ", "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス", "", 98);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102703, 0, "", "vo_empress_102701_003", "vo_empress_102701_003", 4, 5, 2, "エリコ", "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…", "", 99);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102702, 102701, "", "vo_empress_102701_004", "vo_empress_102701_004", 4, 5, 3, "エリコ", "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪", "", 100);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102801, 0, "", "vo_empress_102801_001", "vo_empress_102801_001", 4, 5, 1, "サレン", "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！", "", 101);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102801, 0, 10000, "vo_empress_102801_002", "vo_empress_102801_002", 4, 3, 4002, "サレン", "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？", 1, 102);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102803, 0, "", "vo_empress_102801_003", "vo_empress_102801_003", 4, 5, 2, "サレン", "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！", "", 103);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102802, 102801, "", "vo_empress_102801_004", "vo_empress_102801_004", 4, 5, 3, "サレン", "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！", "", 104);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102903, 0, "", "vo_empress_102901_001", "vo_empress_102901_001", 4, 5, 1, "ノゾミ", "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！", "", 105);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102903, 0, "", "vo_empress_102901_002", "vo_empress_102901_002", 4, 5, 1, "ノゾミ", "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！", "", 106);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102903, 0, "", "vo_empress_102901_003", "vo_empress_102901_003", 4, 5, 2, "ノゾミ", "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！", "", 107);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 102901, 102901, "", "vo_empress_102901_004", "vo_empress_102901_004", 4, 5, 3, "ノゾミ", "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！", "", 108);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103001, 0, "", "vo_empress_103001_001", "vo_empress_103001_001", 4, 5, 1, "ニノン", "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！", "", 109);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103001, 0, "", "vo_empress_103001_002", "vo_empress_103001_002", 4, 5, 1, "ニノン", "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！", "", 110);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103003, 0, "", "vo_empress_103001_003", "vo_empress_103001_003", 4, 5, 2, "ニノン", "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！", "", 111);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103002, 103001, "", "vo_empress_103001_004", "vo_empress_103001_004", 4, 5, 3, "ニノン", "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！", "", 112);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103101, 0, "", "vo_empress_103101_001", "vo_empress_103101_001", 4, 5, 1, "シノブ", "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！", "", 113);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103101, 0, "", "vo_empress_103101_002", "vo_empress_103101_002", 4, 5, 1, "シノブ", "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で", "", 114);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103103, 0, "", "vo_empress_103101_003", "vo_empress_103101_003", 4, 5, 2, "シノブ", "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！", "", 115);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103101, 103101, "", "vo_empress_103101_004", "vo_empress_103101_004", 4, 5, 3, "シノブ", "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！", "", 116);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103201, 0, "", "vo_empress_103201_001", "vo_empress_103201_001", 4, 5, 1, "アキノ", "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！", "", 117);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103201, 0, "", "vo_empress_103201_002", "vo_empress_103201_002", 4, 5, 1, "アキノ", "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！", "", 118);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103203, 0, "", "vo_empress_103201_003", "vo_empress_103201_003", 4, 5, 2, "アキノ", "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！", "", 119);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103202, 103201, "", "vo_empress_103201_004", "vo_empress_103201_004", 4, 5, 3, "アキノ", "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！", "", 120);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103301, 0, "", "vo_empress_103301_001", "vo_empress_103301_001", 4, 5, 1, "マヒル", "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！", "", 121);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103301, 0, "", "vo_empress_103301_002", "vo_empress_103301_002", 4, 5, 1, "マヒル", "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！", "", 122);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103303, 0, "", "vo_empress_103301_003", "vo_empress_103301_003", 4, 5, 2, "マヒル", "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！", "", 123);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103302, 103301, "", "vo_empress_103301_004", "vo_empress_103301_004", 4, 5, 3, "マヒル", "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！", "", 124);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103401, 0, "", "vo_empress_103401_001", "vo_empress_103401_001", 4, 5, 1, "ユカリ", "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！", "", 125);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103401, 0, "", "vo_empress_103401_002", "vo_empress_103401_002", 4, 5, 1, "ユカリ", "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！", "", 126);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103403, 0, "", "vo_empress_103401_003", "vo_empress_103401_003", 4, 5, 2, "ユカリ", "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ", "", 127);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103402, 103401, "", "vo_empress_103401_004", "vo_empress_103401_004", 4, 5, 3, "ユカリ", "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！", "", 128);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103603, 0, "", "vo_empress_103601_001", "vo_empress_103601_001", 4, 5, 1, "キョウカ", "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！", "", 129);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103603, 0, "", "vo_empress_103601_002", "vo_empress_103601_002", 4, 5, 1, "キョウカ", "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！", "", 130);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103601, 0, "", "vo_empress_103601_003", "vo_empress_103601_003", 4, 5, 2, "キョウカ", "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！", "", 131);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103602, 103601, "", "vo_empress_103601_004", "vo_empress_103601_004", 4, 5, 3, "キョウカ", "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます", "", 132);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103701, 0, "", "vo_empress_103701_001", "vo_empress_103701_001", 4, 5, 1, "トモ", "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！", "", 133);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103701, 0, "", "vo_empress_103701_002", "vo_empress_103701_002", 4, 5, 1, "トモ", "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！", "", 134);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103701, 0, "", "vo_empress_103701_003", "vo_empress_103701_003", 4, 5, 2, "トモ", "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！", "", 135);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103702, 103701, "", "vo_empress_103701_004", "vo_empress_103701_004", 4, 5, 3, "トモ", "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！", "", 136);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103801, 0, "", "vo_empress_103801_001", "vo_empress_103801_001", 4, 5, 1, "シオリ", "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから", "", 137);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103801, 0, "", "vo_empress_103801_002", "vo_empress_103801_002", 4, 5, 1, "シオリ", "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？", "", 138);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103803, 0, "", "vo_empress_103801_003", "vo_empress_103801_003", 4, 5, 2, "シオリ", "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！", "", 139);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 103802, 103801, "", "vo_empress_103801_004", "vo_empress_103801_004", 4, 5, 3, "シオリ", "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります", "", 140);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104001, 0, "", "vo_empress_104001_001", "vo_empress_104001_001", 4, 5, 1, "アオイ", "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！", "", 141);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104002, 0, "", "vo_empress_104001_002", "vo_empress_104001_002", 4, 5, 1, "アオイ", "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！", "", 142);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104003, 0, "", "vo_empress_104001_003", "vo_empress_104001_003", 4, 5, 2, "アオイ", "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！", "", 143);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104002, 104001, "", "vo_empress_104001_004", "vo_empress_104001_004", 4, 5, 3, "アオイ", "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！", "", 144);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104203, 0, "", "vo_empress_104201_001", "vo_empress_104201_001", 4, 5, 1, "チカ", "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！", "", 145);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104201, 0, "", "vo_empress_104201_002", "vo_empress_104201_002", 4, 5, 1, "チカ", "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！", "", 146);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104203, 0, "", "vo_empress_104201_003", "vo_empress_104201_003", 4, 5, 2, "チカ", "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！", "", 147);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104201, 104201, "", "vo_empress_104201_004", "vo_empress_104201_004", 4, 5, 3, "チカ", "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！", "", 148);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104301, 0, "", "vo_empress_104301_001", "vo_empress_104301_001", 4, 5, 1, "マコト", "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！", "", 149);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104301, 0, "", "vo_empress_104301_002", "vo_empress_104301_002", 4, 5, 1, "マコト", "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！", "", 150);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104303, 0, "", "vo_empress_104301_003", "vo_empress_104301_003", 4, 5, 2, "マコト", "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！", "", 151);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104302, 104301, "", "vo_empress_104301_004", "vo_empress_104301_004", 4, 5, 3, "マコト", "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！", "", 152);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104401, 0, "", "vo_empress_104401_001", "vo_empress_104401_001", 4, 5, 1, "イリヤ", "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！", "", 153);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104401, 0, "", "vo_empress_104401_002", "vo_empress_104401_002", 4, 5, 1, "イリヤ", "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！", "", 154);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104401, 0, "", "vo_empress_104401_003", "vo_empress_104401_003", 4, 5, 2, "イリヤ", "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ", "", 155);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104401, 104401, "", "vo_empress_104401_004", "vo_empress_104401_004", 4, 5, 3, "イリヤ", "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！", "", 156);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104501, 0, "", "vo_empress_104501_001", "vo_empress_104501_001", 4, 5, 1, "クウカ", "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪", "", 157);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104501, 0, "", "vo_empress_104501_002", "vo_empress_104501_002", 4, 5, 1, "クウカ", "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！", "", 158);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104503, 0, "", "vo_empress_104501_003", "vo_empress_104501_003", 4, 5, 2, "クウカ", "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ", "", 159);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104502, 104501, "", "vo_empress_104501_004", "vo_empress_104501_004", 4, 5, 3, "クウカ", "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました", "", 160);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104601, 0, "", "vo_empress_104601_001", "vo_empress_104601_001", 4, 5, 1, "タマキ", "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？", "", 161);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104601, 0, "", "vo_empress_104601_002", "vo_empress_104601_002", 4, 5, 1, "タマキ", "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！", "", 162);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104603, 0, "", "vo_empress_104601_003", "vo_empress_104601_003", 4, 5, 2, "タマキ", "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！", "", 163);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104602, 104601, "", "vo_empress_104601_004", "vo_empress_104601_004", 4, 5, 3, "タマキ", "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！", "", 164);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104701, 0, "", "vo_empress_104701_001", "vo_empress_104701_001", 4, 5, 1, "ジュン", "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！", "", 165);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104701, 0, "", "vo_empress_104701_002", "vo_empress_104701_002", 4, 5, 1, "ジュン", "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな", "", 166);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104701, 0, "", "vo_empress_104701_003", "vo_empress_104701_003", 4, 5, 2, "ジュン", "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても", "", 167);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104701, 104701, "", "vo_empress_104701_004", "vo_empress_104701_004", 4, 5, 3, "ジュン", "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！", "", 168);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104801, 0, "", "vo_empress_104801_001", "vo_empress_104801_001", 4, 5, 1, "ミフユ", "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！", "", 169);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104801, 0, "", "vo_empress_104801_002", "vo_empress_104801_002", 4, 5, 1, "ミフユ", "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！", "", 170);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104803, 0, "", "vo_empress_104801_003", "vo_empress_104801_003", 4, 5, 2, "ミフユ", "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！", "", 171);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104802, 104801, "", "vo_empress_104801_004", "vo_empress_104801_004", 4, 5, 3, "ミフユ", "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！", "", 172);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104902, 0, "", "vo_empress_104901_001", "vo_empress_104901_001", 4, 5, 1, "シズル", "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！", "", 173);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104902, 0, "", "vo_empress_104901_002", "vo_empress_104901_002", 4, 5, 1, "シズル", "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪", "", 174);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104903, 0, "", "vo_empress_104901_003", "vo_empress_104901_003", 4, 5, 2, "シズル", "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！", "", 175);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 104902, 104901, "", "vo_empress_104901_004", "vo_empress_104901_004", 4, 5, 3, "シズル", "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪", "", 176);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105001, 0, "", "vo_empress_105001_001", "vo_empress_105001_001", 4, 5, 1, "ミサキ", "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！", "", 177);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105001, 0, "", "vo_empress_105001_002", "vo_empress_105001_002", 4, 5, 1, "ミサキ", "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！", "", 178);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105003, 0, "", "vo_empress_105001_003", "vo_empress_105001_003", 4, 5, 2, "ミサキ", "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！", "", 179);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105002, 105001, "", "vo_empress_105001_004", "vo_empress_105001_004", 4, 5, 3, "ミサキ", "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！", "", 180);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105101, 0, "", "vo_empress_105101_001", "vo_empress_105101_001", 4, 5, 1, "ミツキ", "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪", "", 181);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105101, 0, "", "vo_empress_105101_002", "vo_empress_105101_002", 4, 5, 1, "ミツキ", "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい", "", 182);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105101, 0, "", "vo_empress_105101_003", "vo_empress_105101_003", 4, 5, 2, "ミツキ", "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！", "", 183);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105101, 105101, "", "vo_empress_105101_004", "vo_empress_105101_004", 4, 5, 3, "ミツキ", "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！", "", 184);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105201, 0, "", "vo_empress_105201_001", "vo_empress_105201_001", 4, 5, 1, "リマ", "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！", "", 185);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105201, 0, 10000, "vo_empress_105201_002", "vo_empress_105201_002", 4, 3, 4002, "リマ", "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？", 1, 186);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105201, 0, "", "vo_empress_105201_003", "vo_empress_105201_003", 4, 5, 2, "リマ", "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！", "", 187);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105202, 105201, "", "vo_empress_105201_004", "vo_empress_105201_004", 4, 5, 3, "リマ", "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！", "", 188);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105303, 0, "", "vo_empress_105301_001", "vo_empress_105301_001", 4, 5, 1, "モニカ", "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！", "", 189);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105301, 0, "", "vo_empress_105301_002", "vo_empress_105301_002", 4, 5, 1, "モニカ", "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！", "", 190);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105301, 0, "", "vo_empress_105301_003", "vo_empress_105301_003", 4, 5, 2, "モニカ", "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！", "", 191);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105302, 105301, "", "vo_empress_105301_004", "vo_empress_105301_004", 4, 5, 3, "モニカ", "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！", "", 192);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105401, 0, "", "vo_empress_105401_001", "vo_empress_105401_001", 4, 5, 1, "ツムギ", "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！", "", 193);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105403, 0, 10000, "vo_empress_105401_002", "vo_empress_105401_002", 4, 3, 4002, "ツムギ", "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？", 1, 194);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105403, 0, "", "vo_empress_105401_003", "vo_empress_105401_003", 4, 5, 2, "ツムギ", "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！", "", 195);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105401, 105401, "", "vo_empress_105401_004", "vo_empress_105401_004", 4, 5, 3, "ツムギ", "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！", "", 196);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105503, 0, "", "vo_empress_105501_001", "vo_empress_105501_001", 4, 5, 1, "アユミ", "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！", "", 197);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105501, 0, "", "vo_empress_105501_002", "vo_empress_105501_002", 4, 5, 1, "アユミ", "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！", "", 198);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105503, 0, "", "vo_empress_105501_003", "vo_empress_105501_003", 4, 5, 2, "アユミ", "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！", "", 199);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105502, 105501, "", "vo_empress_105501_004", "vo_empress_105501_004", 4, 5, 3, "アユミ", "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！", "", 200);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105601, 0, "", "vo_empress_105601_001", "vo_empress_105601_001", 4, 5, 1, "ルカ", "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか", "", 201);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105601, 0, "", "vo_empress_105601_002", "vo_empress_105601_002", 4, 5, 1, "ルカ", "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！", "", 202);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105603, 0, "", "vo_empress_105601_003", "vo_empress_105601_003", 4, 5, 2, "ルカ", "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！", "", 203);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105602, 105601, "", "vo_empress_105601_004", "vo_empress_105601_004", 4, 5, 3, "ルカ", "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！", "", 204);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105803, 0, "", "vo_empress_105801_001", "vo_empress_105801_001", 4, 5, 1, "ペコリーヌ", "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！", "", 205);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105801, 0, 10000, "vo_empress_105801_002", "vo_empress_105801_002", 4, 3, 4003, "ペコリーヌ", "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！", 1, 206);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105803, 0, "", "vo_empress_105801_003", "vo_empress_105801_003", 4, 5, 2, "ペコリーヌ", "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ", "", 207);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105802, 105801, "", "vo_empress_105801_004", "vo_empress_105801_004", 4, 5, 3, "ペコリーヌ", "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！", "", 208);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105903, 0, "", "vo_empress_105901_001", "vo_empress_105901_001", 4, 5, 1, "コッコロ", "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！", "", 209);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105905, 0, "", "vo_empress_105901_002", "vo_empress_105901_002", 4, 5, 1, "コッコロ", "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…", "", 210);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105903, 0, "", "vo_empress_105901_003", "vo_empress_105901_003", 4, 5, 2, "コッコロ", "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！", "", 211);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 105902, 105901, "", "vo_empress_105901_004", "vo_empress_105901_004", 4, 5, 3, "コッコロ", "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！", "", 212);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106001, 0, 10000, "vo_empress_106001_001", "vo_empress_106001_001", 4, 3, 4005, "キャル", "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！", 1, 213);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106003, 0, "", "vo_empress_106001_002", "vo_empress_106001_002", 4, 5, 1, "キャル", "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！", "", 214);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106003, 0, "", "vo_empress_106001_003", "vo_empress_106001_003", 4, 5, 2, "キャル", "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…", "", 215);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106002, 106001, "", "vo_empress_106001_004", "vo_empress_106001_004", 4, 5, 3, "キャル", "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！", "", 216);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106102, 0, "", "vo_empress_106101_001", "vo_empress_106101_001", 4, 5, 1, "ノウェム", "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！", "", 217);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106101, 0, "", "vo_empress_106101_002", "vo_empress_106101_002", 4, 5, 1, "ノウェム", "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！", "", 218);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106103, 0, "", "vo_empress_106101_003", "vo_empress_106101_003", 4, 5, 2, "ノウェム", "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ", "", 219);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106102, 106101, "", "vo_empress_106101_004", "vo_empress_106101_004", 4, 5, 3, "ノウェム", "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！", "", 220);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106401, 0, "", "vo_empress_106401_001", "vo_empress_106401_001", 4, 5, 1, "シェフィ", "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう", "", 221);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106403, 0, 10000, "vo_empress_106401_002", "vo_empress_106401_002", 4, 3, 4004, "シェフィ", "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！", 1, 222);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106401, 0, "", "vo_empress_106401_003", "vo_empress_106401_003", 4, 5, 2, "シェフィ", "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！", "", 223);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106402, 106401, "", "vo_empress_106401_004", "vo_empress_106401_004", 4, 5, 3, "シェフィ", "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう", "", 224);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106501, 0, "", "vo_empress_106501_001", "vo_empress_106501_001", 4, 5, 1, "カヤ", "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！", "", 225);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106501, 0, "", "vo_empress_106501_002", "vo_empress_106501_002", 4, 5, 1, "カヤ", "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？", "", 226);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106503, 0, "", "vo_empress_106501_003", "vo_empress_106501_003", 4, 5, 2, "カヤ", "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！", "", 227);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106501, 106501, "", "vo_empress_106501_004", "vo_empress_106501_004", 4, 5, 3, "カヤ", "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！", "", 228);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106603, 0, "", "vo_empress_106601_001", "vo_empress_106601_001", 4, 5, 1, "イノリ", "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！", "", 229);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106601, 0, "", "vo_empress_106601_002", "vo_empress_106601_002", 4, 5, 1, "イノリ", "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？", "", 230);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106603, 0, "", "vo_empress_106601_003", "vo_empress_106601_003", 4, 5, 2, "イノリ", "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ", "", 231);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106602, 106601, "", "vo_empress_106601_004", "vo_empress_106601_004", 4, 5, 3, "イノリ", "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！", "", 232);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106701, 0, "", "vo_empress_106701_001", "vo_empress_106701_001", 4, 5, 1, "ホマレ", "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪", "", 233);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106701, 0, "", "vo_empress_106701_002", "vo_empress_106701_002", 4, 5, 1, "ホマレ", "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ", "", 234);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106703, 0, "", "vo_empress_106701_003", "vo_empress_106701_003", 4, 5, 2, "ホマレ", "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…", "", 235);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106702, 106701, "", "vo_empress_106701_004", "vo_empress_106701_004", 4, 5, 3, "ホマレ", "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな", "", 236);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106802, 0, "", "vo_empress_106801_001", "vo_empress_106801_001", 4, 5, 1, "ラビリスタ", "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！", "", 237);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106801, 0, 10000, "vo_empress_106801_002", "vo_empress_106801_002", 4, 3, 4005, "ラビリスタ", "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ", 1, 238);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106801, 0, "", "vo_empress_106801_003", "vo_empress_106801_003", 4, 5, 2, "ラビリスタ", "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！", "", 239);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 106802, 106801, "", "vo_empress_106801_004", "vo_empress_106801_004", 4, 5, 3, "ラビリスタ", "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪", "", 240);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 107001, 0, 10000, "vo_empress_107001_001", "vo_empress_107001_001", 4, 3, 4005, "ネネカ", "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も", 1, 241);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 107001, 0, "", "vo_empress_107001_002", "vo_empress_107001_002", 4, 5, 1, "ネネカ", "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから", "", 242);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 107001, 0, "", "vo_empress_107001_003", "vo_empress_107001_003", 4, 5, 2, "ネネカ", "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を", "", 243);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 107002, 107001, "", "vo_empress_107001_004", "vo_empress_107001_004", 4, 5, 3, "ネネカ", "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…", "", 244);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 107101, 0, "", "vo_empress_107101_001", "vo_empress_107101_001", 4, 5, 1, "クリスティーナ", "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪", "", 245);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 107101, 0, 10000, "vo_empress_107101_002", "vo_empress_107101_002", 4, 3, 4005, "クリスティーナ", "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆", 1, 246);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 107103, 0, "", "vo_empress_107101_003", "vo_empress_107101_003", 4, 5, 2, "クリスティーナ", "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆", "", 247);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 107102, 107101, "", "vo_empress_107101_004", "vo_empress_107101_004", 4, 5, 3, "クリスティーナ", "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！", "", 248);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 110801, 0, "", "vo_empress_110801_001", "vo_empress_110801_001", 4, 5, 1, "クロエ", "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！", "", 249);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 110801, 0, 10000, "vo_empress_110801_002", "vo_empress_110801_002", 4, 3, 4005, "クロエ", "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな", 1, 250);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 110803, 0, "", "vo_empress_110801_003", "vo_empress_110801_003", 4, 5, 2, "クロエ", "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ", "", 251);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 110802, 110801, "", "vo_empress_110801_004", "vo_empress_110801_004", 4, 5, 3, "クロエ", "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす", "", 252);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 110901, 0, "", "vo_empress_110901_001", "vo_empress_110901_001", 4, 5, 1, "チエル", "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！", "", 253);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 110901, 0, "", "vo_empress_110901_002", "vo_empress_110901_002", 4, 5, 1, "チエル", "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！", "", 254);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 110903, 0, "", "vo_empress_110901_003", "vo_empress_110901_003", 4, 5, 2, "チエル", "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？", "", 255);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 110902, 110901, "", "vo_empress_110901_004", "vo_empress_110901_004", 4, 5, 3, "チエル", "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！", "", 256);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 111001, 0, "", "vo_empress_111001_001", "vo_empress_111001_001", 4, 5, 1, "ユニ", "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！", "", 257);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 111001, 0, "", "vo_empress_111001_002", "vo_empress_111001_002", 4, 5, 1, "ユニ", "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ", "", 258);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 111003, 0, "", "vo_empress_111001_003", "vo_empress_111001_003", 4, 5, 2, "ユニ", "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…", "", 259);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 111002, 111001, "", "vo_empress_111001_004", "vo_empress_111001_004", 4, 5, 3, "ユニ", "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！", "", 260);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118001, 0, "", "vo_empress_118001_001", "vo_empress_118001_001", 4, 5, 1, "クレジッタ", "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！", "", 261);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118003, 0, "", "vo_empress_118001_002", "vo_empress_118001_002", 4, 5, 1, "クレジッタ", "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？", "", 262);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118003, 0, "", "vo_empress_118001_003", "vo_empress_118001_003", 4, 5, 2, "クレジッタ", "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？", "", 263);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118002, 118001, "", "vo_empress_118001_004", "vo_empress_118001_004", 4, 5, 3, "クレジッタ", "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！", "", 264);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118101, 0, "", "vo_empress_118101_001", "vo_empress_118101_001", 4, 5, 1, "ランファ", "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…", "", 265);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118101, 0, "", "vo_empress_118101_002", "vo_empress_118101_002", 4, 5, 1, "ランファ", "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…", "", 266);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118103, 0, "", "vo_empress_118101_003", "vo_empress_118101_003", 4, 5, 2, "ランファ", "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？", "", 267);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118102, 118101, "", "vo_empress_118101_004", "vo_empress_118101_004", 4, 5, 3, "ランファ", "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…", "", 268);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118201, 0, 10000, "vo_empress_118201_001", "vo_empress_118201_001", 4, 3, 4005, "ミソラ", "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪", 1, 269);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118201, 0, "", "vo_empress_118201_002", "vo_empress_118201_002", 4, 5, 1, "ミソラ", "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪", "", 270);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118202, 0, "", "vo_empress_118201_003", "vo_empress_118201_003", 4, 5, 2, "ミソラ", "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─", "", 271);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118202, 118201, "", "vo_empress_118201_004", "vo_empress_118201_004", 4, 5, 3, "ミソラ", "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★", "", 272);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118501, 0, "", "vo_empress_118501_001", "vo_empress_118501_001", 4, 5, 1, "カリン", "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！", "", 273);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118502, 0, "", "vo_empress_118501_002", "vo_empress_118501_002", 4, 5, 1, "カリン", "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪", "", 274);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118503, 0, "", "vo_empress_118501_003", "vo_empress_118501_003", 4, 5, 2, "カリン", "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…", "", 275);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118502, 118501, "", "vo_empress_118501_004", "vo_empress_118501_004", 4, 5, 3, "カリン", "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！", "", 276);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118601, 0, "", "vo_empress_118601_001", "vo_empress_118601_001", 4, 5, 1, "ネビア", "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！", "", 277);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118601, 0, "", "vo_empress_118601_002", "vo_empress_118601_002", 4, 5, 1, "ネビア", "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪", "", 278);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118603, 0, "", "vo_empress_118601_003", "vo_empress_118601_003", 4, 5, 2, "ネビア", "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…", "", 279);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 118602, 118601, "", "vo_empress_118601_004", "vo_empress_118601_004", 4, 5, 3, "ネビア", "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！", "", 280);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 122303, 0, "", "vo_empress_122301_001", "vo_empress_122301_001", 4, 5, 1, "ヴァンピィ", "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！", "", 281);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 122302, 0, "", "vo_empress_122301_002", "vo_empress_122301_002", 4, 5, 1, "ヴァンピィ", "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！", "", 282);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 122303, 0, "", "vo_empress_122301_003", "vo_empress_122301_003", 4, 5, 2, "ヴァンピィ", "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！", "", 283);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 122302, 122301, "", "vo_empress_122301_004", "vo_empress_122301_004", 4, 5, 3, "ヴァンピィ", "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！", "", 284);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 123002, 0, "", "vo_empress_123001_001", "vo_empress_123001_001", 4, 5, 1, "アメス", "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪", "", 285);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 123001, 0, "", "vo_empress_123001_002", "vo_empress_123001_002", 4, 5, 1, "アメス", "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…", "", 286);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 123003, 0, "", "vo_empress_123001_003", "vo_empress_123001_003", 4, 5, 2, "アメス", "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！", "", 287);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 123002, 123001, "", "vo_empress_123001_004", "vo_empress_123001_004", 4, 5, 3, "アメス", "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！", "", 288);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 123301, 0, "", "vo_empress_123301_001", "vo_empress_123301_001", 4, 5, 1, "ネア", "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡", "", 289);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 123301, 0, "", "vo_empress_123301_002", "vo_empress_123301_002", 4, 5, 1, "ネア", "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？", "", 290);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 123303, 0, "", "vo_empress_123301_003", "vo_empress_123301_003", 4, 5, 2, "ネア", "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪", "", 291);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 123302, 123301, "", "vo_empress_123301_004", "vo_empress_123301_004", 4, 5, 3, "ネア", "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡", "", 292);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 126401, 0, "", "vo_empress_126401_001", "vo_empress_126401_001", 4, 5, 1, "クローチェ", "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！", "", 293);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 126401, 0, "", "vo_empress_126401_002", "vo_empress_126401_002", 4, 5, 1, "クローチェ", "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！", "", 294);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 126403, 0, "", "vo_empress_126401_003", "vo_empress_126401_003", 4, 5, 2, "クローチェ", "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？", "", 295);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 126402, 126401, "", "vo_empress_126401_004", "vo_empress_126401_004", 4, 5, 3, "クローチェ", "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！", "", 296);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 126501, 0, "", "vo_empress_126501_001", "vo_empress_126501_001", 4, 5, 1, "ライラエル", "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士", "", 297);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 126506, 0, 10000, "vo_empress_126501_002", "vo_empress_126501_002", 4, 3, 4002, "ライラエル", "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！", 1, 298);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 126503, 0, "", "vo_empress_126501_003", "vo_empress_126501_003", 4, 5, 2, "ライラエル", "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…", "", 299);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 126502, 126501, "", "vo_empress_126501_004", "vo_empress_126501_004", 4, 5, 3, "ライラエル", "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を", "", 300);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 127701, 0, 10000, "vo_empress_127701_001", "vo_empress_127701_001", 4, 3, 4002, "リンド", "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！", 1, 301);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 127701, 0, "", "vo_empress_127701_002", "vo_empress_127701_002", 4, 5, 1, "リンド", "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります", "", 302);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 127703, 0, "", "vo_empress_127701_003", "vo_empress_127701_003", 4, 5, 2, "リンド", "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？", "", 303);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 127702, 127701, "", "vo_empress_127701_004", "vo_empress_127701_004", 4, 5, 3, "リンド", "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから", "", 304);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 127801, 0, "", "vo_empress_127801_001", "vo_empress_127801_001", 4, 5, 1, "ヴルム", "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！", "", 305);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 127801, 0, 10000, "vo_empress_127801_002", "vo_empress_127801_002", 4, 3, 4002, "ヴルム", "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ", 1, 306);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 127803, 0, "", "vo_empress_127801_003", "vo_empress_127801_003", 4, 5, 2, "ヴルム", "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…", "", 307);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 127802, 127801, "", "vo_empress_127801_004", "vo_empress_127801_004", 4, 5, 3, "ヴルム", "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります", "", 308);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 129001, 0, 10000, "vo_empress_129001_001", "vo_empress_129001_001", 4, 3, 4005, "エリス", "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる", 1, 309);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 129001, 0, "", "vo_empress_129001_002", "vo_empress_129001_002", 4, 5, 1, "エリス", "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから", "", 310);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 129003, 0, "", "vo_empress_129001_003", "vo_empress_129001_003", 4, 5, 2, "エリス", "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…", "", 311);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 129002, 129001, "", "vo_empress_129001_004", "vo_empress_129001_004", 4, 5, 3, "エリス", "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない", "", 312);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 129601, 0, "", "vo_empress_129601_001", "vo_empress_129601_001", 4, 5, 1, "アネモネ", "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──", "", 313);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 129601, 0, "", "vo_empress_129601_002", "vo_empress_129601_002", 4, 5, 1, "アネモネ", "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど", "", 314);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 129603, 0, "", "vo_empress_129601_003", "vo_empress_129601_003", 4, 5, 2, "アネモネ", "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…", "", 315);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 129601, 129601, "", "vo_empress_129601_004", "vo_empress_129601_004", 4, 5, 3, "アネモネ", "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと", "", 316);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 129701, 0, "", "vo_empress_129701_001", "vo_empress_129701_001", 4, 5, 1, "ネフィ＝ネラ", "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也", "", 317);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 129701, 0, "", "vo_empress_129701_002", "vo_empress_129701_002", 4, 5, 1, "ネフィ＝ネラ", "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう", "", 318);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 129703, 0, "", "vo_empress_129701_003", "vo_empress_129701_003", 4, 5, 2, "ネフィ＝ネラ", "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…", "", 319);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 129702, 129701, "", "vo_empress_129701_004", "vo_empress_129701_004", 4, 5, 3, "ネフィ＝ネラ", "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう", "", 320);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130001, 0, 10000, "vo_empress_130001_001", "vo_empress_130001_001", 4, 3, 4003, "ヤマト", "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ", 1, 321);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130001, 0, "", "vo_empress_130001_002", "vo_empress_130001_002", 4, 5, 1, "ヤマト", "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！", "", 322);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130003, 0, "", "vo_empress_130001_003", "vo_empress_130001_003", 4, 5, 2, "ヤマト", "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…", "", 323);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130002, 130001, "", "vo_empress_130001_004", "vo_empress_130001_004", 4, 5, 3, "ヤマト", "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！", "", 324);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130101, 0, "", "vo_empress_130101_001", "vo_empress_130101_001", 4, 5, 1, "ワカナ", "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ", "", 325);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130101, 0, "", "vo_empress_130101_002", "vo_empress_130101_002", 4, 5, 1, "ワカナ", "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ", "", 326);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130103, 0, "", "vo_empress_130101_003", "vo_empress_130101_003", 4, 5, 2, "ワカナ", "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？", "", 327);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130102, 130101, "", "vo_empress_130101_004", "vo_empress_130101_004", 4, 5, 3, "ワカナ", "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！", "", 328);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130201, 0, "", "vo_empress_130201_001", "vo_empress_130201_001", 4, 5, 1, "フブキ", "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡", "", 329);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130201, 0, "", "vo_empress_130201_002", "vo_empress_130201_002", 4, 5, 1, "フブキ", "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪", "", 330);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130203, 0, "", "vo_empress_130201_003", "vo_empress_130201_003", 4, 5, 2, "フブキ", "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？", "", 331);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130202, 130201, "", "vo_empress_130201_004", "vo_empress_130201_004", 4, 5, 3, "フブキ", "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡", "", 332);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130901, 0, "", "vo_empress_130901_001", "vo_empress_130901_001", 4, 5, 1, "クルル", "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！", "", 333);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130901, 0, "", "vo_empress_130901_002", "vo_empress_130901_002", 4, 5, 1, "クルル", "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？", "", 334);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130903, 0, "", "vo_empress_130901_003", "vo_empress_130901_003", 4, 5, 2, "クルル", "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！", "", 335);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 130902, 130901, "", "vo_empress_130901_004", "vo_empress_130901_004", 4, 5, 3, "クルル", "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！", "", 336);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 132301, 0, "", "vo_empress_132301_001", "vo_empress_132301_001", 4, 5, 1, "ルイズマリー", "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！", "", 337);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 132301, 0, "", "vo_empress_132301_002", "vo_empress_132301_002", 4, 5, 1, "ルイズマリー", "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！", "", 338);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 132303, 0, "", "vo_empress_132301_003", "vo_empress_132301_003", 4, 5, 2, "ルイズマリー", "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！", "", 339);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 132302, 132301, "", "vo_empress_132301_004", "vo_empress_132301_004", 4, 5, 3, "ルイズマリー", "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！", "", 340);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 132401, 0, "", "vo_empress_132401_001", "vo_empress_132401_001", 4, 5, 1, "イロハ", "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！", "", 341);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 132401, 0, "", "vo_empress_132401_002", "vo_empress_132401_002", 4, 5, 1, "イロハ", "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！", "", 342);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 132401, 0, "", "vo_empress_132401_003", "vo_empress_132401_003", 4, 5, 2, "イロハ", "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！", "", 343);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 132402, 132401, "", "vo_empress_132401_004", "vo_empress_132401_004", 4, 5, 3, "イロハ", "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！", "", 344);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 132501, 0, "", "vo_empress_132501_001", "vo_empress_132501_001", 4, 5, 1, "ソノ", "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…", "", 345);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 132501, 0, "", "vo_empress_132501_002", "vo_empress_132501_002", 4, 5, 1, "ソノ", "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね", "", 346);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 132503, 0, "", "vo_empress_132501_003", "vo_empress_132501_003", 4, 5, 2, "ソノ", "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！", "", 347);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 132502, 132501, "", "vo_empress_132501_004", "vo_empress_132501_004", 4, 5, 3, "ソノ", "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪", "", 348);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 133001, 0, "", "vo_empress_133001_001", "vo_empress_133001_001", 4, 5, 1, "グレイス", "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね", "", 349);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 133003, 0, 10000, "vo_empress_133001_002", "vo_empress_133001_002", 4, 3, 4001, "グレイス", "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる", 1, 350);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 133003, 0, "", "vo_empress_133001_003", "vo_empress_133001_003", 4, 5, 2, "グレイス", "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！", "", 351);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 133002, 133001, "", "vo_empress_133001_004", "vo_empress_133001_004", 4, 5, 3, "グレイス", "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ", "", 352);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 133101, 0, "", "vo_empress_133101_001", "vo_empress_133101_001", 4, 5, 1, "ヴァイオレット", "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！", "", 353);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 133101, 0, 10000, "vo_empress_133101_002", "vo_empress_133101_002", 4, 3, 4001, "ヴァイオレット", "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！", 1, 354);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 133103, 0, "", "vo_empress_133101_003", "vo_empress_133101_003", 4, 5, 2, "ヴァイオレット", "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…", "", 355);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 133102, 133101, "", "vo_empress_133101_004", "vo_empress_133101_004", 4, 5, 3, "ヴァイオレット", "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！", "", 356);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 133601, 0, "", "vo_empress_133601_001", "vo_empress_133601_001", 4, 5, 1, "メドゥーサ", "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！", "", 357);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 133601, 0, "", "vo_empress_133601_002", "vo_empress_133601_002", 4, 5, 1, "メドゥーサ", "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！", "", 358);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 133603, 0, "", "vo_empress_133601_003", "vo_empress_133601_003", 4, 5, 2, "メドゥーサ", "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！", "", 359);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 133602, 133601, "", "vo_empress_133601_004", "vo_empress_133601_004", 4, 5, 3, "メドゥーサ", "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！", "", 360);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 134701, 0, "", "vo_empress_134701_001", "vo_empress_134701_001", 4, 5, 1, "ホウオウ", "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！", "", 361);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 134701, 0, "", "vo_empress_134701_002", "vo_empress_134701_002", 4, 5, 1, "ホウオウ", "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！", "", 362);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 134703, 0, "", "vo_empress_134701_003", "vo_empress_134701_003", 4, 5, 2, "ホウオウ", "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…", "", 363);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 134702, 134701, "", "vo_empress_134701_004", "vo_empress_134701_004", 4, 5, 3, "ホウオウ", "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！", "", 364);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 134901, 0, "", "vo_empress_134901_001", "vo_empress_134901_001", 4, 5, 1, "カノン", "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！", "", 365);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 134901, 0, "", "vo_empress_134901_002", "vo_empress_134901_002", 4, 5, 1, "カノン", "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！", "", 366);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 134903, 0, "", "vo_empress_134901_003", "vo_empress_134901_003", 4, 5, 2, "カノン", "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！", "", 367);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 134902, 134901, "", "vo_empress_134901_004", "vo_empress_134901_004", 4, 5, 3, "カノン", "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪", "", 368);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135501, 0, "", "vo_empress_135501_001", "vo_empress_135501_001", 4, 5, 1, "アイラ", "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！", "", 369);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135501, 0, 10000, "vo_empress_135501_002", "vo_empress_135501_002", 4, 3, 4005, "アイラ", "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！", 1, 370);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135503, 0, "", "vo_empress_135501_003", "vo_empress_135501_003", 4, 5, 2, "アイラ", "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！", "", 371);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135502, 135501, "", "vo_empress_135501_004", "vo_empress_135501_004", 4, 5, 3, "アイラ", "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！", "", 372);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135601, 0, "", "vo_empress_135601_001", "vo_empress_135601_001", 4, 5, 1, "シナツ", "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…", "", 373);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135601, 0, "", "vo_empress_135601_002", "vo_empress_135601_002", 4, 5, 1, "シナツ", "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ", "", 374);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135603, 0, "", "vo_empress_135601_003", "vo_empress_135601_003", 4, 5, 2, "シナツ", "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！", "", 375);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135602, 135601, "", "vo_empress_135601_004", "vo_empress_135601_004", 4, 5, 3, "シナツ", "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！", "", 376);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135801, 0, 10000, "vo_empress_135801_001", "vo_empress_135801_001", 4, 3, 4001, "ユキノ", "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！", 1, 377);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135801, 0, "", "vo_empress_135801_002", "vo_empress_135801_002", 4, 5, 1, "ユキノ", "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！", "", 378);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135803, 0, "", "vo_empress_135801_003", "vo_empress_135801_003", 4, 5, 2, "ユキノ", "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！", "", 379);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135802, 135801, "", "vo_empress_135801_004", "vo_empress_135801_004", 4, 5, 3, "ユキノ", "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！", "", 380);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135903, 0, 10000, "vo_empress_135901_001", "vo_empress_135901_001", 4, 3, 4001, "サツキ", "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ", 1, 381);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135901, 0, "", "vo_empress_135901_002", "vo_empress_135901_002", 4, 5, 1, "サツキ", "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか", "", 382);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135901, 0, "", "vo_empress_135901_003", "vo_empress_135901_003", 4, 5, 2, "サツキ", "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか", "", 383);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 135902, 135901, "", "vo_empress_135901_004", "vo_empress_135901_004", 4, 5, 3, "サツキ", "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ", "", 384);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 136001, 0, "", "vo_empress_136001_001", "vo_empress_136001_001", 4, 5, 1, "アラクネ", "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします", "", 385);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 136001, 0, 10000, "vo_empress_136001_002", "vo_empress_136001_002", 4, 3, 4003, "アラクネ", "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…", 1, 386);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 136003, 0, "", "vo_empress_136001_003", "vo_empress_136001_003", 4, 5, 2, "アラクネ", "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…", "", 387);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 136002, 136001, "", "vo_empress_136001_004", "vo_empress_136001_004", 4, 5, 3, "アラクネ", "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま", "", 388);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 136201, 0, "", "vo_empress_136201_001", "vo_empress_136201_001", 4, 5, 1, "ナーナ", "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪", "", 389);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 136201, 0, "", "vo_empress_136201_002", "vo_empress_136201_002", 4, 5, 1, "ナーナ", "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！", "", 390);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 136201, 0, "", "vo_empress_136201_003", "vo_empress_136201_003", 4, 5, 2, "ナーナ", "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！", "", 391);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 136202, 136201, "", "vo_empress_136201_004", "vo_empress_136201_004", 4, 5, 3, "ナーナ", "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！", "", 392);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 136903, 0, 10000, "vo_empress_136901_001", "vo_empress_136901_001", 4, 3, 4001, "ルルィ", "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！", 1, 393);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 136901, 0, "", "vo_empress_136901_002", "vo_empress_136901_002", 4, 5, 1, "ルルィ", "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！", "", 394);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 136903, 0, "", "vo_empress_136901_003", "vo_empress_136901_003", 4, 5, 2, "ルルィ", "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！", "", 395);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 136902, 136901, "", "vo_empress_136901_004", "vo_empress_136901_004", 4, 5, 3, "ルルィ", "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！", "", 396);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 139501, 0, "", "vo_empress_139501_001", "vo_empress_139501_001", 4, 5, 1, "リリ", "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ", "", 397);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 139503, 0, 10000, "vo_empress_139501_002", "vo_empress_139501_002", 4, 3, 4002, "リリ", "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！", 1, 398);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 139503, 0, "", "vo_empress_139501_003", "vo_empress_139501_003", 4, 5, 2, "リリ", "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず", "", 399);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 139502, 125801, "", "vo_empress_139501_004", "vo_empress_139501_004", 4, 5, 3, "リリ", "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！", "", 400);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 139603, 0, "", "vo_empress_139601_001", "vo_empress_139601_001", 4, 5, 1, "クリア", "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！", "", 401);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 139603, 0, 10000, "vo_empress_139601_002", "vo_empress_139601_002", 4, 3, 4002, "クリア", "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！", 1, 402);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 139603, 0, "", "vo_empress_139601_003", "vo_empress_139601_003", 4, 5, 2, "クリア", "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！", "", 403);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 139601, 126001, "", "vo_empress_139601_004", "vo_empress_139601_004", 4, 5, 3, "クリア", "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！", "", 404);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 139701, 0, "", "vo_empress_139701_001", "vo_empress_139701_001", 4, 5, 1, "プレシア", "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー", "", 405);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 139701, 0, "", "vo_empress_139701_002", "vo_empress_139701_002", 4, 5, 1, "プレシア", "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい", "", 406);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 139703, 0, "", "vo_empress_139701_003", "vo_empress_139701_003", 4, 5, 2, "プレシア", "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで", "", 407);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 139702, 126101, "", "vo_empress_139701_004", "vo_empress_139701_004", 4, 5, 3, "プレシア", "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！", "", 408);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 140301, 140301, "", "vo_empress_140301_004", "vo_empress_140301_004", 4, 5, 3, "ティア", "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪", "", 409);
